import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

public class TransactionPipelineDeduplicator {
    public static <T> List<T> deduplicatePreservingOrder(List<T> stream) {
        if (stream == null || stream.isEmpty()) {
            return List.of();
        }
        // LinkedHashSet guarantees both O(1) deduplication and FIFO sequence preservation
        Set<T> uniqueOrdered = new LinkedHashSet<>(stream);
        return List.copyOf(uniqueOrdered);
    }

    public static void main(String[] args) {
        List<String> userEvents = List.of(
            "LOGIN", "VIEW_ITEM", "ADD_TO_CART", "VIEW_ITEM", 
            "CHECKOUT", "LOGIN", "CONFIRM"
        );

        List<String> cleanSequence = deduplicatePreservingOrder(userEvents);
        System.out.println("Original events count: " + userEvents.size());
        System.out.println("Cleaned events count:  " + cleanSequence.size());
        System.out.println("Deterministic order:   " + cleanSequence);
    }
}

